// get name and sim position of Avatars within "say" range
default
{
state_entry
()
{
llOwnerSay
(
"Touch me to get the positions of avatars in 'Say' range"
);
}
touch_start
(
integer
vIntTouchCount
)
{
// Do a one-off sensor sweep over a 20m radius sphere for avatars
llSensor
(
""
,
""
,
AGENT
,
20
,
PI
);
}
sensor
(
integer
vIntFound
)
{
integer
vIntCounter
=
0
;
//-- loop through all avatars found
do
{
llOwnerSay
(
llDetectedName
(
vIntCounter
)
// get the position of this detected avatar
+
(
string
)
llDetectedPos
(
vIntCounter
)
);
}
while
(
++
vIntCounter
<
vIntFound
);
}
// sensor does not detect owner if it's attached
no_sensor
()
{
llOwnerSay
(
"I couldn't find anybody"
);
}
}
